  reload_usage: { en: 'Usage: `/reload [--skip-build]`\nRebuilds the host face and restarts the daemon — the same as running reload.sh from a plain terminal. `--skip-build` skips the build when it was done elsewhere.\nMid-turn sessions lose the current turn (it rolls back to the last complete turn).', zh: '用法：`/reload [--skip-build]`\n重建 host 面并重启 daemon——等同在普通终端执行 reload.sh。构建已在别处完成时用 `--skip-build` 跳过。\n进行中的回合会回滚到最后完整回合。' },
  reload_started: { en: '🔄 Reload started: building, then restarting the daemon (the build takes a few minutes; `--skip-build` restarts within seconds). Mid-turn sessions roll back to their last complete turn. Log: %s', zh: '🔄 Reload 已启动：先构建再重启 daemon（构建需数分钟；`--skip-build` 数秒内完成重启）。进行中的回合会回滚到最后完整回合。日志: %s' },
  reload_completed: { en: '✅ Reload complete: the daemon restarted (this notice is sent by the new process). Build and WS-probe details in the log: %s', zh: '✅ Reload 完成：daemon 已重启（本通知由新进程发出）。构建与 WS 探活详情见日志: %s' },
  reload_failed: { en: '❌ Reload failed (exit code %d); the daemon was not restarted. Log: %s', zh: '❌ Reload 失败（退出码 %d），daemon 未重启。日志: %s' },
